93	        torch::Tensor state, double lr, double beta1, double beta2, double eps,
94	        double weight_decay, double bc1, double bc2, int64_t step,
95	        double alpha, double lamb, double gamma, int64_t ncta_cap) {
96	    TORCH_CHECK(params.is_cuda() && params.scalar_type() == torch::kFloat32 && params.is_contiguous());
97	    TORCH_CHECK(params.numel() == kMambaTotalElems, "params must be the flat mamba blob (", kMambaTotalElems, ")");
98	    TORCH_CHECK(tokens.is_cuda() && tokens.scalar_type() == torch::kInt32 && tokens.is_contiguous());
99	    TORCH_CHECK(targets.is_cuda() && targets.scalar_type() == torch::kInt32 && targets.is_contiguous());
100	    const int B = (int)targets.numel();
101	    TORCH_CHECK(tokens.numel() == (int64_t)B * mb::kSeq, "tokens must be [B,kSeq]");
102	    TORCH_CHECK((B % 16) == 0, "TC path requires B % 16 == 0");
103	    const int64_t total = kMambaTotalElems;
104	    TORCH_CHECK(state.is_cuda() && state.scalar_type() == torch::kFloat32 && state.is_contiguous()
105	                && state.numel() >= 3 * total, "state must be contiguous fp32 [>=3*total]");
106	
107	    const int nCTA = tc_effective_nctas(params, (int)ncta_cap);
108	    TcScratch& sc = tc_scratch_for(params, B, nCTA);
109	    auto grad = torch::zeros({total}, torch::dtype(torch::kFloat32).device(params.device()));
110	    auto loss_dev = torch::zeros({1}, torch::dtype(torch::kFloat32).device(params.device()));
111	
112	    PersistentContext ctx{
113	        sc.g_next.data_ptr<int>(),
114	        reinterpret_cast<unsigned*>(sc.g_arrived.data_ptr<int>()),
115	        reinterpret_cast<unsigned*>(sc.g_generation.data_ptr<int>()),
116	        kMambaNumTensors, 0u};
117	
118	    float* m = state.data_ptr<float>();
119	    float* const extra_slice = m + 2 * total;
120	    FusedOptState st;
121	    st.exp_avg = m;
122	    st.exp_avg_sq = m + total;
123	    st.ema = extra_slice;
124	    st.psi_W1 = extra_slice + kPsiW1Off;
125	    st.psi_b1 = extra_slice + kPsiB1Off;
126	    st.psi_W2 = extra_slice + kPsiW2Off;
127	
128	    FusedScalars scal;
129	    scal.lr = (float)lr; scal.beta1 = (float)beta1; scal.beta2 = (float)beta2;
130	    scal.eps = (float)eps; scal.wd = (float)weight_decay;
131	    scal.bc1 = (float)bc1; scal.bc2 = (float)bc2;
132	    scal.alpha = (float)alpha; scal.lamb = (float)lamb; scal.gamma = (float)gamma;
133	    apply_scalars(st, scal);
134	    st.lr = (float)lr;
135	
136	    MambaTokenCtx tok;
137	    tok.tokens = tokens.data_ptr<int>();
138	    tok.targets = targets.data_ptr<int>();
139	    tok.B = B;
140	    tok.workspace = sc.workspace.data_ptr<float>();
141	    tok.loss_out = loss_dev.data_ptr<float>();
142	
143	    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
144	    cudaError_t err = launch_opt((int)opt_id, ctx, params.data_ptr<float>(), tok,
145	                                 grad.data_ptr<float>(), (float)lr, (int)step, st, stream, nCTA);
146	    TORCH_CHECK(err == cudaSuccess, "TC mamba megakernel launch failed (opt_id=", opt_id, "): ",
147	                cudaGetErrorString(err));
148	    C10_CUDA_CHECK(cudaStreamSynchronize(stream));
149	    return {loss_dev.to(torch::kCPU), grad};
150	}
