1272	// (occ·n_sms with occupancy-fill, or the cap). The caller MUST size the workspace
1273	// with this — the per-CTA scratch/partials are nCTA·slab, so sizing for n_sms while
1274	// the launcher runs occ·n_sms would overflow. Returns 0 on a CUDA-attr failure (the
1275	// caller should treat that as "fall back to a conservative larger size").
1276	template <OptId Opt>
1277	int mb_tc_launched_nctas(int dev, int ncta_cap) {
1278	    int n_sms = 0;
1279	    if (cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev) != cudaSuccess) return 0;
1280	    // MAMBA-3: the per-sample MambaSampleSmem (~227 KB) is DYNAMIC smem → one
1281	    // block/SM (occ=1) by design. Query occ with the REAL dynamic-smem request
1282	    // (and opt in first, else the query assumes the 48 KB static default).
1283	    const int dyn_smem = (int)kMambaSmemBytes;
1284	    cudaFuncSetAttribute((const void*)&fused_mamba_megakernel_tc<Opt>,
1285	                         cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1286	    int occ = 0;
1287	    if (cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1288	            &occ, (const void*)&fused_mamba_megakernel_tc<Opt>, SG_MB_TC_MEGA_BLOCK, dyn_smem) != cudaSuccess)
1289	        return 0;
1290	    if (occ < 1) return 0;
1291	    unsigned launch_ctas = (unsigned)n_sms;   // one CTA/SM (smem-bound)
1292	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1293	    return (int)launch_ctas;
1294	}
