1297	cudaError_t launch_fused_mamba_megakernel_tc(
1298	        PersistentContext ctx, float* params, MambaTokenCtx tok,
1299	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1300	        int ncta_cap = 0, const ::sg::fused::par::CommCtx& comm = {}) {
1301	    int dev = 0;
1302	    cudaError_t err = cudaGetDevice(&dev);
1303	    if (err != cudaSuccess) return err;
1304	    int n_sms = 0;
1305	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1306	    if (err != cudaSuccess) return err;
1307	
1308	    // MAMBA-3: DYNAMIC smem opt-in (the per-sample MambaSampleSmem ~227 KB). Three
1309	    // mandatory steps (cudaFuncSetAttribute + dyn_smem in the occ query + dyn_smem
1310	    // at <<<>>>); one block/SM by design (occ=1, smem-bound).
1311	    const int dyn_smem = (int)kMambaSmemBytes;
1312	    err = cudaFuncSetAttribute((const void*)&fused_mamba_megakernel_tc<Opt, Par>,
1313	                               cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1314	    if (err != cudaSuccess) return err;
1315	    int occ = 0;
1316	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1317	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt, Par>, SG_MB_TC_MEGA_BLOCK,
1318	        /*dynamicSMemBytes=*/dyn_smem);
1319	    if (err != cudaSuccess) return err;
1320	    if (occ < 1) return cudaErrorLaunchOutOfResources;
1321	
1322	    unsigned launch_ctas = (unsigned)n_sms;   // one CTA/SM (smem-bound); deterministic per fixed nCTA
1323	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
1324	    ctx.n_ctas = launch_ctas;
1325	    // B%16 kept (the gate truncates B to a multiple of 16; the scalar per-sample
1326	    // path needs no tile alignment but the contract upstream assumes B%16).
1327	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
1328	    // TP lockstep precondition (kTPComm only): the grid-lockstep-over-samples P1
1329	    // (kernel M-C) partitions nCTA into Par::kTP contiguous PE groups, so nCTA must
1330	    // divide by TP. Byte-identical when OFF (Par::kTPComm folds to false).
1331	    if constexpr (Par::kTPComm) {
1332	        if ((launch_ctas % (unsigned)Par::kTP) != 0) return cudaErrorInvalidValue;
1333	    }
1334	
1335	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
1336	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
1337	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
1338	
1339	    dim3 grid(launch_ctas), block(SG_MB_TC_MEGA_BLOCK);
1340	    fused_mamba_megakernel_tc<Opt, Par><<<grid, block, dyn_smem, stream>>>(
1341	        ctx, params, tok, grad, lr, step, st, comm);
1342	    return cudaGetLastError();
1343	}
