56	        s.g_generation = torch::zeros({1}, oi);
57	    }
58	    s.n_ctas = nCTA;
59	    if (s.ws_floats < need) {
60	        s.workspace = torch::empty({need}, torch::dtype(torch::kFloat32).device(params.device()));
61	        s.ws_floats = need;
62	    }
63	    return s;
